function getInfraPinsForLayer(layerType, refLat, refLng, radiusKm) {
  if (!refLat || !refLng) return [];
  const results = [];
  switch (layerType) {
    case "metro": {
      for (const pin of SMART_PINS.filter((p2) => p2.type === "metro")) {
        const dist = haversineDistance(refLat, refLng, pin.lat, pin.lng);
        if (dist <= radiusKm)
          results.push({
            name: pin.name,
            lat: pin.lat,
            lng: pin.lng,
            distance: dist,
            emoji: "🚇"
          });
      }
      break;
    }
    case "railway": {
      for (const pin of SMART_PINS.filter((p2) => p2.type === "railway")) {
        const dist = haversineDistance(refLat, refLng, pin.lat, pin.lng);
        if (dist <= radiusKm)
          results.push({
            name: pin.name,
            lat: pin.lat,
            lng: pin.lng,
            distance: dist,
            emoji: "🚆"
          });
      }
      break;
    }
    case "bus_stop": {
      for (const pin of SMART_PINS.filter((p2) => p2.type === "bus_stop")) {
        const dist = haversineDistance(refLat, refLng, pin.lat, pin.lng);
        if (dist <= radiusKm)
          results.push({
            name: pin.name,
            lat: pin.lat,
            lng: pin.lng,
            distance: dist,
            emoji: "🚌"
          });
      }
      break;
    }
    case "hospital": {
      for (const pin of SMART_PINS.filter((p2) => p2.type === "hospital")) {
        const dist = haversineDistance(refLat, refLng, pin.lat, pin.lng);
        if (dist <= radiusKm)
          results.push({
            name: pin.name,
            lat: pin.lat,
            lng: pin.lng,
            distance: dist,
            emoji: "🏥"
          });
      }
      break;
    }
    case "school": {
      for (const pin of SMART_PINS.filter((p2) => p2.type === "school")) {
        const dist = haversineDistance(refLat, refLng, pin.lat, pin.lng);
        if (dist <= radiusKm)
          results.push({
            name: pin.name,
            lat: pin.lat,
            lng: pin.lng,
            distance: dist,
            emoji: "🏫"
          });
      }
      break;
    }
    case "tech_park": {
      for (const pin of SMART_PINS.filter((p2) => p2.type === "tech_park")) {
        const dist = haversineDistance(refLat, refLng, pin.lat, pin.lng);
        if (dist <= radiusKm)
          results.push({
            name: pin.name,
            lat: pin.lat,
            lng: pin.lng,
            distance: dist,
            emoji: "💼"
          });
      }
      break;
    }
    case "college": {
      for (const pin of COLLEGES) {
        const dist = haversineDistance(refLat, refLng, pin.lat, pin.lng);
        if (dist <= radiusKm)
          results.push({
            name: pin.name,
            lat: pin.lat,
            lng: pin.lng,
            distance: dist,
            emoji: "🎓"
          });
      }
      break;
    }
    case "mall": {
      for (const pin of MALLS) {
        const dist = haversineDistance(refLat, refLng, pin.lat, pin.lng);
        if (dist <= radiusKm)
          results.push({
            name: pin.name,
            lat: pin.lat,
            lng: pin.lng,
            distance: dist,
            emoji: "🛍️"
          });
      }
      break;
    }
    case "airport": {
      for (const pin of AIRPORTS) {
        const dist = haversineDistance(refLat, refLng, pin.lat, pin.lng);
        if (dist <= radiusKm)
          results.push({
            name: pin.name,
            lat: pin.lat,
            lng: pin.lng,
            distance: dist,
            emoji: "✈️"
          });
      }
      break;
    }
    case "highway": {
      for (const pin of HIGHWAYS) {
        const dist = haversineDistance(refLat, refLng, pin.lat, pin.lng);
        if (dist <= radiusKm)
          results.push({
            name: pin.name,
            lat: pin.lat,
            lng: pin.lng,
            distance: dist,
            emoji: "🛣️"
          });
      }
      break;
    }
  }
  return results.sort((a2, b2) => a2.distance - b2.distance);
}
function getInfraRadiusForZoom(zoom) {
  if (zoom >= 14) return 3;
  if (zoom >= 12) return 5;
  return 10;
}
function getHeatmapConfig(level) {
  switch (level) {
    case "smart":
      return {
        gradient: { 0.2: "#3B82F6", 0.5: "#6366F1", 1: "#8B5CF6" },
        minOpacity: 0.3,
        maxZoom: 18,
        radius: 25
      };
    case "premium":
      return {
        gradient: { 0.2: "#B45309", 0.5: "#D97706", 1: "#D8B56A" },
        minOpacity: 0.3,
        maxZoom: 18,
        radius: 25
      };
    case "growth":
      return {
        gradient: { 0.2: "#059669", 0.5: "#10B981", 1: "#34D399" },
        minOpacity: 0.3,
        maxZoom: 18,
        radius: 25
      };
    case "investment":
      return {
        gradient: { 0.2: "#7C3AED", 0.5: "#8B5CF6", 1: "#A78BFA" },
        minOpacity: 0.3,
        maxZoom: 18,
        radius: 25
      };
  }
}
