const SMART_PINS = [
  // Phase 1 — HIGH priority (render on top)
  ...TECH_PARKS.map((tp, i) => ({
    id: `techpark-${i}`,
    type: "tech_park",
    priority: "high",
    name: tp.name,
    lat: tp.lat,
    lng: tp.lng,
    emoji: "🏢",
    employees: TECH_PARK_EMPLOYEES[tp.name] ?? Math.round(tp.weight * 25e3),
    impactTag: "High rental driver",
    impactDescription: "Drives rental demand ↑"
  })),
  ...METROS.map((m2, i) => ({
    id: `metro-${i}`,
    type: "metro",
    priority: "high",
    name: m2.name,
    lat: m2.lat,
    lng: m2.lng,
    emoji: "🚇",
    line: m2.line,
    impactTag: "Connectivity boost",
    impactDescription: "Metro access improves property value"
  })),
  // Phase 2 — MEDIUM priority
  ...BUS_STOPS.map((b2, i) => ({
    ...b2,
    id: `bus-${i}`,
    priority: "medium"
  })),
  ...RAILWAY_STATIONS.map((r2, i) => ({
    ...r2,
    id: `rail-${i}`,
    priority: "medium"
  })),
  // Phase 3 — LOW priority
  ...HOSPITALS.map((h2, i) => ({
    ...h2,
    id: `hospital-${i}`,
    priority: "low"
  })),
  ...SCHOOLS.map((s2, i) => ({
    ...s2,
    id: `school-${i}`,
    priority: "low"
  }))
];
function getSmartPins(lat, lng, radiusKm = 20) {
  const priorityOrder = {
    high: 0,
    medium: 1,
    low: 2
  };
  const filtered = !lat || !lng ? SMART_PINS : SMART_PINS.filter(
    (pin) => haversineDistance(lat, lng, pin.lat, pin.lng) <= radiusKm
  );
  return [...filtered].sort(
    (a2, b2) => priorityOrder[a2.priority] - priorityOrder[b2.priority]
  );
}
