function getMicroLocationByName(name) {
  if (!name) return void 0;
  const lower = name.toLowerCase().trim();
  let found = bangaloreMicroLocations.find(
    (l2) => l2.name.toLowerCase() === lower
  );
  if (found) return found;
  found = bangaloreMicroLocations.find(
    (l2) => l2.name.toLowerCase().includes(lower) || lower.includes(l2.name.toLowerCase())
  );
  return found;
}
function getPincodeForLocality(name) {
  const loc = getMicroLocationByName(name);
  return (loc == null ? void 0 : loc.pincode) ?? "";
}
function getLocationsByZone() {
  const groups = {
    North: [],
    East: [],
    South: [],
    West: [],
    Central: []
  };
  for (const loc of bangaloreMicroLocations) {
    groups[loc.zone].push(loc);
  }
  return groups;
}
function getOrderedLocations() {
  const popular = bangaloreMicroLocations.filter((l2) => l2.isPopular);
  const rest = bangaloreMicroLocations.filter((l2) => !l2.isPopular);
  return [...popular, ...rest];
}
