function recordToFeatures(r2) {
  return [
    1,
    r2.sqft,
    r2.localityIndex,
    r2.propertyTypeIndex,
    r2.demandScore,
    r2.metroDistance,
    r2.infraScore,
    r2.pastAvgPrice
  ];
}
function dotProduct(a2, b2) {
  return a2.reduce((sum, v2, i) => sum + v2 * b2[i], 0);
}
function trainWeightedLinearRegression(records) {
  if (records.length < 3)
    return {
      weights: new Array(FEATURE_NAMES.length).fill(0),
      mae: 9999,
      rmse: 9999
    };
  const n2 = records.length;
  const numFeatures = FEATURE_NAMES.length;
  const X2 = records.map(recordToFeatures);
  const y2 = records.map((r2) => r2.pricePerSqft);
  function getRecencyMultiplier(month) {
    if (month === void 0) return 1;
    if (month >= 10) return 5;
    if (month === 9) return 2.5;
    if (month === 8) return 1.8;
    if (month === 7) return 1.3;
    return 1;
  }
  const sampleWeights = records.map((r2) => {
    const sourceW = r2.source === "real" ? REAL_DATA_WEIGHT : BUILDER_DATA_WEIGHT;
    const recencyW = getRecencyMultiplier(r2.month);
    return sourceW * recencyW;
  });
  const featureMeans = new Array(numFeatures).fill(0);
  const featureStds = new Array(numFeatures).fill(1);
  const totalWeight = sampleWeights.reduce((s2, w2) => s2 + w2, 0);
  for (let j2 = 1; j2 < numFeatures; j2++) {
    featureMeans[j2] = X2.reduce((s2, row, i) => s2 + row[j2] * sampleWeights[i], 0) / totalWeight;
    const variance = X2.reduce(
      (s2, row, i) => s2 + sampleWeights[i] * (row[j2] - featureMeans[j2]) ** 2,
      0
    ) / totalWeight;
    featureStds[j2] = Math.sqrt(variance) || 1;
  }
  const Xn = X2.map(
    (row) => row.map((v2, j2) => j2 === 0 ? 1 : (v2 - featureMeans[j2]) / featureStds[j2])
  );
  let weights = new Array(numFeatures).fill(0);
  const lr = 0.01;
  const epochs = 1200;
  for (let e3 = 0; e3 < epochs; e3++) {
    const grad = new Array(numFeatures).fill(0);
    for (let i = 0; i < n2; i++) {
      const pred = dotProduct(Xn[i], weights);
      const err = (pred - y2[i]) * sampleWeights[i];
      for (let j2 = 0; j2 < numFeatures; j2++) grad[j2] += err * Xn[i][j2];
    }
    for (let j2 = 0; j2 < numFeatures; j2++)
      weights[j2] -= lr / totalWeight * grad[j2];
  }
  const realWeights = new Array(numFeatures).fill(0);
  let biasCorrection = 0;
  for (let j2 = 1; j2 < numFeatures; j2++) {
    realWeights[j2] = weights[j2] / featureStds[j2];
    biasCorrection += realWeights[j2] * featureMeans[j2];
  }
  realWeights[0] = weights[0] - biasCorrection;
  const preds = records.map(
    (r2) => dotProduct(recordToFeatures(r2), realWeights)
  );
  const wErrors = preds.map((p2, i) => sampleWeights[i] * Math.abs(p2 - y2[i]));
  const mae = wErrors.reduce((s2, v2) => s2 + v2, 0) / totalWeight;
  const rmse = Math.sqrt(
    preds.reduce((s2, p2, i) => s2 + sampleWeights[i] * (p2 - y2[i]) ** 2, 0) / totalWeight
  );
  return { weights: realWeights, mae, rmse };
}
