function getDealScore(fairValue, listingPrice) {
  const raw = (fairValue - listingPrice) / fairValue * 100;
  const score = Math.round(Math.min(Math.max(50 + raw * 1.67, 0), 100));
  const pctDiff = Math.round(raw * 10) / 10;
  let classification;
  let classificationColor;
  if (score >= 75) {
    classification = "Strong Buy";
    classificationColor = "#22c55e";
  } else if (score >= 60) {
    classification = "Good Deal";
    classificationColor = "#84cc16";
  } else if (score >= 40) {
    classification = "Fair Price";
    classificationColor = "#eab308";
  } else {
    classification = "Overpriced";
    classificationColor = "#ef4444";
  }
  const label = pctDiff > 0 ? `${pctDiff.toFixed(1)}% undervalued` : pctDiff < 0 ? `${Math.abs(pctDiff).toFixed(1)}% overpriced` : "At market value";
  return { score, classification, classificationColor, pctDiff, label };
}
function getRecommendation(dealScore, dealClassification, pctGrowth1Y, locationScore, demandScore, growthClassification) {
  const composite = dealScore * 0.4 + Math.min(pctGrowth1Y * 10, 100) * 0.25 + locationScore * 0.2 + demandScore * 0.15;
  if (composite >= 70 && growthClassification === "High Growth") {
    return {
      action: "Strong Buy",
      actionColor: "#22c55e",
      text: `Strong Buy — High growth area with ${dealClassification === "Strong Buy" ? "significantly undervalued" : "favorable"} pricing. Ideal for long-term investment.`,
      confidence: Math.min(Math.round(composite), 95)
    };
  }
  if (composite >= 60) {
    return {
      action: "Buy",
      actionColor: "#84cc16",
      text: `Good Buy — ${growthClassification} area with ${dealClassification.toLowerCase()} pricing. Strong fundamentals support appreciation.`,
      confidence: Math.min(Math.round(composite), 90)
    };
  }
  if (composite >= 45) {
    return {
      action: "Hold",
      actionColor: "#eab308",
      text: `Hold — Fair pricing with ${growthClassification.toLowerCase()} growth outlook. Reasonable entry if buying for self-use.`,
      confidence: Math.min(Math.round(composite), 80)
    };
  }
  return {
    action: "Avoid",
    actionColor: "#ef4444",
    text: `Avoid — ${dealClassification === "Overpriced" ? "Property is overpriced" : "Below-average fundamentals"} with limited near-term upside. Better opportunities available.`,
    confidence: Math.min(Math.round(composite), 75)
  };
}
