function deriveMarketStage(status, launchYear, completionYear) {
  if (status === "Ready") return "Completed";
  if (status === "Pre-Launch") return "Pre-Launch";
  const progress2 = (2026 - launchYear) / Math.max(1, completionYear - launchYear) * 100;
  if (progress2 < 30) return "Early Construction";
  if (progress2 < 70) return "Mid Construction";
  return "Near Completion";
}
