function computeNearestMetroDist(lat, lng) {
  let minDist = Number.POSITIVE_INFINITY;
  for (const m2 of METRO_STATIONS_COORDS) {
    const d2 = haversineDistance(lat, lng, m2.lat, m2.lng);
    if (d2 < minDist) minDist = d2;
  }
  return Math.round(minDist * 10) / 10;
}
