function classifyMarket(input) {
  const { lat, lng, priceGrowthPercent, supplyLevel, infraScore, demandScore } = input;
  const zone = getZoneType(lat, lng);
  let classification;
  let reason;
  if (priceGrowthPercent >= 15 && supplyLevel === "low" && infraScore < 50) {
    classification = "Emerging";
    reason = "High growth potential with limited supply and developing infrastructure";
  } else if (priceGrowthPercent >= 8 && priceGrowthPercent < 20 && demandScore >= 60 && infraScore >= 40) {
    classification = "Growth Corridor";
    reason = "Strong demand growth with improving infrastructure and rising prices";
  } else if (priceGrowthPercent >= 5 && priceGrowthPercent <= 14 && infraScore >= 65 && demandScore >= 55) {
    classification = "Established";
    reason = "Mature market with stable growth, strong infrastructure, and steady demand";
  } else if (supplyLevel === "high" && priceGrowthPercent < 8 && demandScore < 50) {
    classification = "Saturated";
    reason = "High supply with low demand growth and slowing price appreciation";
  } else if (priceGrowthPercent >= 12) {
    classification = "Growth Corridor";
    reason = "Above-average price growth signals emerging corridor";
  } else if (infraScore >= 70) {
    classification = "Established";
    reason = "Strong infrastructure base supports stable market";
  } else {
    classification = "Emerging";
    reason = "Developing area with growth potential";
  }
  let isValid = true;
  let validationNote;
  if (classification === "Saturated" && zone === "peripheral") {
    classification = "Emerging";
    reason = "Peripheral developing area reclassified from Saturated to Emerging";
    isValid = false;
    validationNote = "Peripheral areas cannot be Saturated — insufficient market maturity";
  }
  if (classification === "Saturated" && priceGrowthPercent > 12) {
    classification = "Growth Corridor";
    reason = "Reclassified: high price growth is inconsistent with Saturated market";
    isValid = false;
    validationNote = `Growth of ${priceGrowthPercent}% disqualifies Saturated classification`;
  }
  if (classification === "Emerging" && infraScore > 75) {
    classification = "Established";
    reason = "Strong infrastructure base reclassified from Emerging to Established";
    isValid = false;
    validationNote = `Infra score ${infraScore} is too high for Emerging classification`;
  }
  if (classification === "Established" && priceGrowthPercent < 5) {
    classification = "Saturated";
    reason = "Low price growth in mature area indicates market saturation";
    isValid = false;
    validationNote = `Growth of ${priceGrowthPercent}% in mature area suggests saturation`;
  }
  if (zone === "semiUrban" && priceGrowthPercent >= 10 && (classification === "Saturated" || classification === "Emerging")) {
    classification = "Growth Corridor";
    reason = "Semi-urban area with strong growth corridor characteristics";
    isValid = false;
    validationNote = "Reclassified to Growth Corridor based on zone + growth signals";
  }
  const confidence = computeConfidence(
    priceGrowthPercent,
    supplyLevel,
    infraScore,
    demandScore
  );
  return { classification, confidence, reason, isValid, validationNote };
}
function computeConfidence(priceGrowth, supply, infra, demand) {
  let score = 50;
  if (priceGrowth > 12) score += 15;
  else if (priceGrowth > 8) score += 10;
  else if (priceGrowth < 5) score -= 10;
  if (supply === "low") score += 10;
  else if (supply === "high") score += 5;
  if (infra > 70) score += 10;
  else if (infra < 30) score -= 5;
  if (demand > 70) score += 10;
  else if (demand < 40) score -= 5;
  return Math.min(Math.max(score, 20), 95);
}
function classifyFromLocality(lat, lng, localityName) {
  const zone = getZoneType(lat, lng);
  let priceGrowthPercent;
  let supplyLevel;
  let infraScore;
  let demandScore;
  switch (zone) {
    case "urban":
      priceGrowthPercent = 8;
      supplyLevel = "medium";
      infraScore = 80;
      demandScore = 72;
      break;
    case "semiUrban":
      priceGrowthPercent = 12;
      supplyLevel = "medium";
      infraScore = 52;
      demandScore = 60;
      break;
    default:
      priceGrowthPercent = 16;
      supplyLevel = "low";
      infraScore = 30;
      demandScore = 45;
      break;
  }
  const lname = (localityName ?? "").toLowerCase();
  if (lname.includes("whitefield") || lname.includes("sarjapur") || lname.includes("bellandur") || lname.includes("hebbal")) {
    priceGrowthPercent = 11;
    infraScore = 72;
    demandScore = 75;
  } else if (lname.includes("devanahalli") || lname.includes("bagalur") || lname.includes("aerospace")) {
    priceGrowthPercent = 18;
    infraScore = 38;
    demandScore = 50;
  } else if (lname.includes("electronic city") || lname.includes("hosur")) {
    priceGrowthPercent = 10;
    infraScore = 68;
    demandScore = 68;
  }
  return classifyMarket({
    lat,
    lng,
    priceGrowthPercent,
    supplyLevel,
    infraScore,
    demandScore
  });
}
