const ZONE_GROWTH = {
  "East Bangalore": 0.92,
  "North Bangalore": 0.85,
  "South Bangalore": 0.8,
  "West Bangalore": 0.72,
  "Central Bangalore": 0.95
};
function scoreProject(p2) {
  const avgPrice = (p2.price_min + p2.price_max) / 2;
  for (const m2 of METROS) {
    haversineDistance(p2.latitude, p2.longitude, m2.lat, m2.lng);
  }
  const metroFactor = getMetroFactor(p2.latitude, p2.longitude);
  const zoneWeight = ZONE_GROWTH[p2.zone] ?? 0.8;
  const locationScore = Math.round(
    (metroFactor - 0.95) / 0.15 * 60 + zoneWeight * 40
  );
  const techScore = getRawTechScore(p2.latitude, p2.longitude);
  const amenityScore = getRawAmenityScore(p2.latitude, p2.longitude);
  const priceInCr = avgPrice / 1e7;
  const rawPriceScore = priceInCr <= 0.8 ? 95 : priceInCr <= 1.5 ? 85 : priceInCr <= 3 ? 70 : priceInCr <= 5 ? 55 : 35;
  const launchBonus = p2.launch_year >= 2024 ? 10 : p2.launch_year >= 2022 ? 5 : 0;
  const growthScore = Math.round(
    Math.min(techScore * 60 + zoneWeight * 30 + launchBonus, 100)
  );
  const builderScore = getBuilderScoreNum(p2.builder);
  const statusBonus = p2.status === "Ready" ? 10 : p2.status === "Pre-Launch" ? -5 : 0;
  const livabilityScore = Math.round(Math.min(amenityScore * 80 + 20, 100));
  const raw = locationScore * 0.28 + growthScore * 0.22 + builderScore * 0.2 + rawPriceScore * 0.15 + livabilityScore * 0.1 + statusBonus * 0.05;
  const investmentScore = Math.round(Math.min(Math.max(raw, 20), 98));
  let tag;
  if (avgPrice > 3e7) {
    tag = "Luxury";
  } else if (avgPrice > 15e6 && investmentScore >= 65) {
    tag = "Premium";
  } else if (avgPrice <= 8e6) {
    tag = "Budget Pick";
  } else {
    tag = "Best Value";
  }
  return {
    investmentScore,
    tag,
    subScores: {
      location: Math.round(Math.min(Math.max(locationScore, 0), 100)),
      price: rawPriceScore,
      growth: growthScore,
      builder: builderScore
    },
    avgPrice
  };
}
