const R = 6371;
function haversineMetres(lat1, lng1, lat2, lng2) {
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLng = (lng2 - lng1) * Math.PI / 180;
  const a2 = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a2), Math.sqrt(1 - a2)) * 1e3;
}
function reverseGeocodeLocally(lat, lng) {
  const candidates = bangaloreMicroLocations.map((m2) => ({
    name: m2.name,
    lat: m2.lat,
    lng: m2.lng,
    pincode: m2.pincode,
    zone: m2.zone,
    parentArea: m2.parentArea
  }));
  const knownNames = new Set(candidates.map((c2) => c2.name.toLowerCase()));
  for (const [key, coords] of Object.entries(ALL_LOCALITY_COORDS)) {
    const normalised = key.split(" ").map((w2) => w2.charAt(0).toUpperCase() + w2.slice(1)).join(" ");
    if (!knownNames.has(normalised.toLowerCase())) {
      candidates.push({
        name: normalised,
        lat: coords.lat,
        lng: coords.lng,
        pincode: "",
        zone: "Other",
        parentArea: "Bangalore"
      });
    }
  }
  const withDistance = candidates.map((c2) => ({
    ...c2,
    distM: haversineMetres(lat, lng, c2.lat, c2.lng)
  }));
  withDistance.sort((a2, b2) => a2.distM - b2.distM);
  const nearest = withDistance[0];
  const EXACT_RADIUS_M = 500;
  if (nearest.distM <= EXACT_RADIUS_M) {
    const method = nearest.distM <= 200 ? "exact" : "within_500m";
    return buildResult(lat, lng, nearest, method, false);
  }
  const MAX_SEARCH_KM = 2e3;
  if (nearest.distM <= MAX_SEARCH_KM) {
    return buildResult(lat, lng, nearest, "nearest_approximate", true);
  }
  return {
    locality: "Custom Location",
    microLocation: "",
    city: "Bangalore",
    pincode: "",
    zone: "",
    parentArea: "",
    lat,
    lng,
    method: "custom",
    isApproximate: true,
    displayLabel: "Custom Location"
  };
}
function buildResult(lat, lng, c2, method, isApproximate) {
  const approximateTag = isApproximate ? " (approx.)" : "";
  const areaLabel = c2.parentArea || c2.zone || "Bangalore";
  const pinLabel = c2.pincode ? ` - ${c2.pincode}` : "";
  const displayLabel = `${c2.name}${approximateTag}, ${areaLabel}${pinLabel}`;
  return {
    locality: c2.name,
    microLocation: c2.name,
    city: "Bangalore",
    pincode: c2.pincode,
    zone: c2.zone,
    parentArea: c2.parentArea,
    lat,
    lng,
    method,
    isApproximate,
    displayLabel
  };
}
function loadLeafletForMap() {
  return new Promise((resolve, reject) => {
    if (window.L) {
      resolve(window.L);
      return;
    }
    if (!document.getElementById("leaflet-css")) {
      const link = document.createElement("link");
      link.id = "leaflet-css";
      link.rel = "stylesheet";
      link.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
      document.head.appendChild(link);
    }
    if (!document.getElementById("leaflet-js")) {
      const script = document.createElement("script");
      script.id = "leaflet-js";
      script.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
      script.onload = () => resolve(window.L);
      script.onerror = () => reject(new Error("Failed to load Leaflet"));
      document.head.appendChild(script);
    } else {
      const interval = setInterval(() => {
        if (window.L) {
          clearInterval(interval);
          resolve(window.L);
        }
      }, 50);
      setTimeout(() => {
        clearInterval(interval);
        reject(new Error("timeout"));
      }, 1e4);
    }
  });
}
