function nameSimilarity(name, query) {
  const n2 = name.toLowerCase();
  const q2 = query.toLowerCase().trim();
  if (n2 === q2) return 100;
  if (n2.startsWith(q2)) return 80;
  if (n2.includes(q2)) return 60;
  let common = 0;
  for (const c2 of q2) if (n2.includes(c2)) common++;
  return Math.round(common / Math.max(n2.length, q2.length) * 40);
}
